        shape_size = np.frombuffer(data[4:8], dtype=np.uint32).item()
        shape = []
        for i in range(shape_size):
            dim = np.frombuffer(data[8 + i * 4:8 + (i + 1) * 4], dtype=np.uint32).item()
            shape.append(dim)
        start_index = 8 + shape_size * 4
        tensor_data = torch.frombuffer(data[start_index:], dtype=dtype)
        return tensor_data.reshape(tuple(shape), dtype=dtype)

    def can_serialize(self, item: Any) -> bool:
        return isinstance(item, torch.Tensor)
