def _upload_fn(upload_queue: Queue, remove_queue: Queue, cache_dir: str, output_dir: Dir) -> None:

    s3 = S3Client().client()  # Initialize S3 client

    while True:
        item = upload_queue.get()
        if item is None:
            break  # Termination signal received

        if isinstance(item, str):
            # Single file path
            file_path = item
            temp_dir = cache_dir
        else:
            # Tuple (temp_dir, file_path)
            temp_dir, file_path = item

        # Adjust file path to be relative to cache_dir
        if not file_path.startswith(cache_dir):
            file_path = os.path.join(cache_dir, file_path)

        # Determine the correct upload method based on the output directory's scheme
        if output_dir.url and output_dir.url.startswith("s3://"):
            # Output directory is an S3 URL
            s3.upload_file(file_path, output_dir.url.replace("s3://", ""), os.path.basename(file_path))
        elif os.path.isdir(output_dir):
            # Output directory is a local directory
            shutil.copy2(file_path, output_dir)
        else:
            raise ValueError("Unsupported output directory scheme.")

        # Add file path to remove_queue if it still exists
        if os.path.exists(file_path):
            remove_queue.put(file_path)
