    def phrase_freq(self, tokens: List[str], slop=1) -> np.ndarray:
        if slop == 1 and len(set(tokens)) == len(tokens):
            # Calculate phrase frequencies directly using positions
            positions_matrix = np.zeros((len(self), len(tokens)))
            for i, doc in enumerate(self):
                doc_positions = self.positions(tokens[0], i)
                for j, token in enumerate(tokens[1:]):
                    doc_positions = np.intersect1d(doc_positions, self.positions(token, i))
                    if len(doc_positions) == 0:
                        break
                if len(doc_positions) > 0:
                    positions_matrix[i, :] = np.arange(len(doc_positions))
